body.script:
/**/
(function () {
  var status = document.getElementById("status");
  function show(message) {
    if (status) status.textContent = message;
  }
  var base = new URL(".", location.href);
  var app = new URL("app.html", base).href;
  var sw = new URL("sw.js", base).href;
  var done = false;

  function go() {
    if (done) return;
    done = true;
    location.replace(app + location.search + location.hash);
  }

  if (!("serviceWorker" in navigator)) {
    show("Loading...");
    return;
  }

  show("Loading...");
  navigator.serviceWorker.register(sw, { scope: base.href, updateViaCache: "none" })
    .then(function (reg) {
      return navigator.serviceWorker.ready.then(function () { return reg; });
    })
    .then(function (reg) {
      if (navigator.serviceWorker.controller || (reg && reg.active)) {
        go();
        return;
      }
      navigator.serviceWorker.addEventListener("controllerchange", go, { once: true });
      setTimeout(go, 2000);
    })
    .catch(function (err) {
      show("Load failed: " + (err && err.message ? err.message : err));
    });
})();
/**/
